from collections import deque
class Solution:
    def minMoves(self, classroom, energy):
        m, n = len(classroom), len(classroom[0])
        lid = {}
        sr = sc = 0
        for i in range(m):
            for j in range(n):
                ch = classroom[i][j]
                if ch == 'L': lid[(i, j)] = len(lid)
                elif ch == 'S': sr, sc = i, j
        full = (1 << len(lid)) - 1
        seen = {(sr, sc, 0, energy)}
        q = deque([(sr, sc, 0, energy)])
        steps = 0
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
        while q:
            for _ in range(len(q)):
                r, c, mk, e = q.popleft()
                if mk == full: return steps
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < m and 0 <= nc < n) or classroom[nr][nc] == 'X' or e == 0:
                        continue
                    ne, nmk = e - 1, mk
                    ch = classroom[nr][nc]
                    if ch == 'R': ne = energy
                    elif ch == 'L': nmk |= 1 << lid[(nr, nc)]
                    st = (nr, nc, nmk, ne)
                    if st not in seen:
                        seen.add(st)
                        q.append(st)
            steps += 1
        return -1

