class Solution {
public:
    int minMoves(vector<string>& classroom, int energy) {
        int m = classroom.size(), n = classroom[0].size();
        vector<vector<int>> lid(m, vector<int>(n, -1));
        int sr = 0, sc = 0, L = 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (classroom[i][j] == 'L') lid[i][j] = L++;
            if (classroom[i][j] == 'S') { sr = i; sc = j; }
        }
        int full = (1 << L) - 1;
        unordered_set<long long> seen;
        queue<array<int,4>> q;
        auto enc = [&](int r, int c, int mk, int e) {
            return (((long long)r * n + c) << 10 | mk) << 6 | e;
        };
        seen.insert(enc(sr, sc, 0, energy));
        q.push({sr, sc, 0, energy});
        int steps = 0, dr[] = {1,-1,0,0}, dc[] = {0,0,1,-1};
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                auto cur = q.front(); q.pop();
                int r = cur[0], c = cur[1], mk = cur[2], e = cur[3];
                if (mk == full) return steps;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nc < 0 || nr >= m || nc >= n || classroom[nr][nc] == 'X' || e == 0) continue;
                    int ne = e - 1, nmk = mk;
                    char ch = classroom[nr][nc];
                    if (ch == 'R') ne = energy;
                    else if (ch == 'L') nmk |= 1 << lid[nr][nc];
                    long long k = enc(nr, nc, nmk, ne);
                    if (seen.insert(k).second) q.push({nr, nc, nmk, ne});
                }
            }
            steps++;
        }
        return -1;
    }
};

