class Solution {
    public int minMoves(String[] classroom, int energy) {
        int m = classroom.length, n = classroom[0].length();
        int[][] lid = new int[m][n];
        int sr = 0, sc = 0, L = 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            lid[i][j] = -1;
            char ch = classroom[i].charAt(j);
            if (ch == 'L') lid[i][j] = L++;
            if (ch == 'S') { sr = i; sc = j; }
        }
        int full = (1 << L) - 1;
        Set<Long> seen = new HashSet<>();
        Deque<long[]> q = new ArrayDeque<>();
        seen.add(enc(sr, sc, 0, energy, n));
        q.add(new long[]{sr, sc, 0, energy});
        int steps = 0;
        int[] dr = {1,-1,0,0}, dc = {0,0,1,-1};
        while (!q.isEmpty()) {
            int sz = q.size();
            while (sz-- > 0) {
                long[] cur = q.poll();
                int r = (int)cur[0], c = (int)cur[1], mk = (int)cur[2], e = (int)cur[3];
                if (mk == full) return steps;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nc < 0 || nr >= m || nc >= n || classroom[nr].charAt(nc) == 'X' || e == 0) continue;
                    int ne = e - 1, nmk = mk;
                    char ch = classroom[nr].charAt(nc);
                    if (ch == 'R') ne = energy;
                    else if (ch == 'L') nmk |= 1 << lid[nr][nc];
                    long k = enc(nr, nc, nmk, ne, n);
                    if (seen.add(k)) q.add(new long[]{nr, nc, nmk, ne});
                }
            }
            steps++;
        }
        return -1;
    }
    private long enc(int r, int c, int mk, int e, int n) {
        return (((long) r * n + c) << 10 | mk) << 6 | e;
    }
}

