var minMoves = function(classroom, energy) {
    const m = classroom.length, n = classroom[0].length;
    const lid = Array.from({length: m}, () => Array(n).fill(-1));
    let sr = 0, sc = 0, L = 0;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        if (classroom[i][j] === 'L') lid[i][j] = L++;
        if (classroom[i][j] === 'S') { sr = i; sc = j; }
    }
    const full = (1 << L) - 1;
    const seen = new Set([sr + ',' + sc + ',0,' + energy]);
    let q = [[sr, sc, 0, energy]], steps = 0;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (q.length) {
        const nx = [];
        for (const [r, c, mk, e] of q) {
            if (mk === full) return steps;
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
                const ch = classroom[nr][nc];
                if (ch === 'X' || e === 0) continue;
                let ne = e - 1, nmk = mk;
                if (ch === 'R') ne = energy;
                else if (ch === 'L') nmk |= 1 << lid[nr][nc];
                const key = nr + ',' + nc + ',' + nmk + ',' + ne;
                if (!seen.has(key)) { seen.add(key); nx.push([nr, nc, nmk, ne]); }
            }
        }
        q = nx; steps++;
    }
    return -1;
};
